// Fold every feed entry into ONE timeline filing.
//
// Each entry must begin with an ISO date: that is what lets Newsdesk trim the
// window against this stringer's watermark. Everything in the window is filed —
// a stringer does not judge newsworthiness, the charter does.

const stripTags = (html = '') =>
  String(html).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();

const entries = items
  .map((item) => item.json)
  .map((entry) => ({
    title: stripTags(entry.title),
    link: entry.link || entry.guid || '',
    at: entry.isoDate || (entry.pubDate ? new Date(entry.pubDate).toISOString() : null),
    summary: stripTags(entry.contentSnippet || entry.content || entry.description || ''),
  }))
  .filter((entry) => entry.title && entry.at)
  .slice(0, 15);

if (entries.length === 0) {
  return [];
}

const text = entries
  .map((entry) => {
    const summary = entry.summary ? `\n  ${entry.summary.slice(0, 600)}` : '';
    const link = entry.link ? `\n  ${entry.link}` : '';
    return `- ${entry.at} ${entry.title}${summary}${link}`;
  })
  .join('\n');

return [{ json: { stringer_id: 'korben', kind: 'timeline', text } }];
